const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '同频同相正弦波叠加' },
      { kind: 'text', payload: '波1  A=1' },
      { kind: 'text', payload: '波2  A=0.5' },
      { kind: 'text', payload: '合成  A=1.5' },
      { kind: 'text', payload: 't' },
      { kind: 'text', payload: 'y' },
      { kind: 'text', payload: '1.5' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '0.5' },
      { kind: 'text', payload: '-1.5' },
      { kind: 'text', payload: '合成振幅 1.5' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var left = 62;
    var right = W - 30;
    var top = 64;
    var bottom = H - 42;
    var midY = (top + bottom) / 2;
    var ampScale = Math.min((bottom - top) * 0.34, 104);
    var x0 = left;
    var x1 = right;
    var cycles = 2;
    var steps = 240;

    function wave(amp) {
      var pts = [];
      for (var i = 0; i <= steps; i++) {
        var u = i / steps;
        var x = x0 + (x1 - x0) * u;
        var y = midY - amp * ampScale * Math.sin(u * Math.PI * 2 * cycles);
        pts.push([x, y]);
      }
      return visualSdk.polyline(pts);
    }

    var xAxis = visualSdk.arrow(x0 - 10, midY, x1 + 8, midY, {});
    var yAxis = visualSdk.arrow(x0, bottom + 10, x0, top - 10, {});
    var tickCommands = [];
    var tickValues = [1.5, 1, 0.5, -1.5];
    for (var t = 0; t < tickValues.length; t++) {
      var ty = midY - tickValues[t] * ampScale;
      tickCommands = tickCommands.concat(visualSdk.polyline([[x0 - 4, ty], [x0 + 4, ty]]));
    }
    var guide15 = visualSdk.polyline([[x0, midY - 1.5 * ampScale], [x1, midY - 1.5 * ampScale]]);
    var peakU = 1 / 8;
    var peakX = x0 + (x1 - x0) * peakU;
    var peakY = midY - 1.5 * ampScale;
    var peakDot = visualSdk.circle(peakX, peakY, 4);
    var legend1X = x0 + 6;
    var legend2X = x0 + (x1 - x0) * 0.18;
    var legend3X = x0 + (x1 - x0) * 0.42;

    return {
      schemaVersion: 1,
      sceneId: 'sine-superposition',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'xAxis', commands: xAxis },
        { id: 'yAxis', commands: yAxis },
        { id: 'ticks', commands: tickCommands },
        { id: 'guide15', commands: guide15 },
        { id: 'wave1', commands: wave(1) },
        { id: 'wave2', commands: wave(0.5) },
        { id: 'sum', commands: wave(1.5) },
        { id: 'peakDot', commands: peakDot }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'guide15', fill: 'none', stroke: { color: '#cfd8e3', width: 1 } },
          { type: 'path', pathId: 'xAxis', fill: 'none', stroke: { color: '#26354a', width: 1.8 } },
          { type: 'path', pathId: 'yAxis', fill: 'none', stroke: { color: '#26354a', width: 1.8 } },
          { type: 'path', pathId: 'ticks', fill: 'none', stroke: { color: '#26354a', width: 1.4 } },
          { type: 'path', pathId: 'wave1', fill: 'none', stroke: { color: '#2f6fb0', width: 2.6 } },
          { type: 'path', pathId: 'wave2', fill: 'none', stroke: { color: '#2a9d8f', width: 2.6 } },
          { type: 'path', pathId: 'sum', fill: 'none', stroke: { color: '#d1495b', width: 2.8 } },
          { type: 'path', pathId: 'peakDot', fill: '#d1495b', stroke: { color: '#d1495b', width: 1 } },
          { type: 'label', contentId: 'c0', anchor: { x: (x0 + x1) / 2, y: 20 }, hAlign: 'center', vAlign: 'middle', color: '#26354a' },
          { type: 'label', contentId: 'c1', anchor: { x: legend1X, y: 44 }, hAlign: 'left', vAlign: 'middle', color: '#2f6fb0' },
          { type: 'label', contentId: 'c2', anchor: { x: legend2X, y: 44 }, hAlign: 'left', vAlign: 'middle', color: '#2a9d8f' },
          { type: 'label', contentId: 'c3', anchor: { x: legend3X, y: 44 }, hAlign: 'left', vAlign: 'middle', color: '#d1495b' },
          { type: 'label', contentId: 'c4', anchor: { x: x1, y: midY + 20 }, hAlign: 'right', vAlign: 'middle', color: '#26354a' },
          { type: 'label', contentId: 'c5', anchor: { x: x0 - 10, y: top - 8 }, hAlign: 'right', vAlign: 'middle', color: '#26354a' },
          { type: 'label', contentId: 'c6', anchor: { x: x0 - 8, y: midY - 1.5 * ampScale }, hAlign: 'right', vAlign: 'middle', color: '#26354a' },
          { type: 'label', contentId: 'c7', anchor: { x: x0 - 8, y: midY - ampScale }, hAlign: 'right', vAlign: 'middle', color: '#26354a' },
          { type: 'label', contentId: 'c8', anchor: { x: x0 - 8, y: midY - 0.5 * ampScale }, hAlign: 'right', vAlign: 'middle', color: '#26354a' },
          { type: 'label', contentId: 'c9', anchor: { x: x0 - 8, y: midY + 1.5 * ampScale }, hAlign: 'right', vAlign: 'middle', color: '#26354a' },
          { type: 'label', contentId: 'c10', anchor: { x: peakX + 10, y: peakY - 8 }, hAlign: 'left', vAlign: 'bottom', color: '#d1495b' }
        ]
      }
    };
  }
};
